create table public.posts (id uuid primary key default gen_random_uuid(), author_id uuid not null references public.profiles(id) on delete restrict, campus_id uuid references public.campuses(id) on delete restrict, body text not null default '', visibility text not null default 'campus', status text not null default 'published', published_at timestamptz not null default timezone('utc',now()), edited_at timestamptz, created_at timestamptz not null default timezone('utc',now()), updated_at timestamptz not null default timezone('utc',now()), deleted_at timestamptz, search_document tsvector generated always as (to_tsvector('simple',coalesce(body,''))) stored, constraint posts_visibility check(visibility in ('private','campus','public')), constraint posts_status check(status in ('draft','published','hidden','removed')));
create table public.post_media (id uuid primary key default gen_random_uuid(), post_id uuid not null references public.posts(id) on delete cascade, media_asset_id uuid not null references public.media_assets(id) on delete restrict, position smallint not null, alt_text text not null default '', created_at timestamptz not null default timezone('utc',now()), unique(post_id,position),unique(post_id,media_asset_id));
create table public.post_comments (id uuid primary key default gen_random_uuid(), post_id uuid not null references public.posts(id) on delete cascade, author_id uuid not null references public.profiles(id) on delete restrict, parent_id uuid references public.post_comments(id) on delete restrict, body text not null, status text not null default 'published', created_at timestamptz not null default timezone('utc',now()), updated_at timestamptz not null default timezone('utc',now()), deleted_at timestamptz, constraint post_comments_status check(status in ('published','hidden','removed')));
create table public.post_likes (post_id uuid not null references public.posts(id) on delete cascade, user_id uuid not null references public.profiles(id) on delete cascade, created_at timestamptz not null default timezone('utc',now()), primary key(post_id,user_id));
create table public.post_polls (id uuid primary key default gen_random_uuid(), post_id uuid not null unique references public.posts(id) on delete cascade, question text not null, closes_at timestamptz, anonymous_results boolean not null default false, created_at timestamptz not null default timezone('utc',now()), constraint post_polls_question check(length(question) between 1 and 500));
create table public.poll_options (id uuid primary key default gen_random_uuid(), poll_id uuid not null references public.post_polls(id) on delete cascade, label text not null, position smallint not null, created_at timestamptz not null default timezone('utc',now()), unique(poll_id,position));
create table public.poll_votes (poll_id uuid not null references public.post_polls(id) on delete cascade, voter_id uuid not null references public.profiles(id) on delete cascade, option_id uuid not null references public.poll_options(id) on delete cascade, created_at timestamptz not null default timezone('utc',now()), primary key(poll_id,voter_id));
create table public.stories (id uuid primary key default gen_random_uuid(), author_id uuid not null references public.profiles(id) on delete restrict, media_asset_id uuid not null references public.media_assets(id) on delete restrict, campus_id uuid references public.campuses(id) on delete restrict, visibility text not null default 'campus', status text not null default 'active', expires_at timestamptz not null, created_at timestamptz not null default timezone('utc',now()), updated_at timestamptz not null default timezone('utc',now()), deleted_at timestamptz, constraint stories_expiry check(expires_at > created_at), constraint stories_visibility check(visibility in ('campus','public')), constraint stories_status check(status in ('active','hidden','removed','expired')));
create table public.story_views (story_id uuid not null references public.stories(id) on delete cascade, viewer_id uuid not null references public.profiles(id) on delete cascade, viewed_at timestamptz not null default timezone('utc',now()), primary key(story_id,viewer_id));
create index posts_feed_idx on public.posts(campus_id,published_at desc,id desc) where deleted_at is null and status='published'; create index posts_author_idx on public.posts(author_id,published_at desc,id desc) where deleted_at is null; create index posts_search_idx on public.posts using gin(search_document); create index post_media_asset_idx on public.post_media(media_asset_id); create index post_comments_thread_idx on public.post_comments(post_id,created_at,id) where deleted_at is null; create index post_comments_parent_idx on public.post_comments(parent_id,created_at); create index poll_options_poll_idx on public.poll_options(poll_id); create index poll_votes_option_idx on public.poll_votes(option_id); create index stories_expiry_idx on public.stories(expires_at) where deleted_at is null;
create trigger posts_set_updated_at before update on public.posts for each row execute function public.set_updated_at(); create trigger post_comments_set_updated_at before update on public.post_comments for each row execute function public.set_updated_at(); create trigger stories_set_updated_at before update on public.stories for each row execute function public.set_updated_at();
create or replace function public.can_read_post(p public.posts) returns boolean language sql stable security definer set search_path=public as $$ select p.deleted_at is null and p.status='published' and (p.author_id=auth.uid() or p.visibility='public' or (p.visibility='campus' and p.campus_id=(select campus_id from public.profiles where id=auth.uid()))); $$;
alter table public.posts enable row level security; alter table public.post_media enable row level security; alter table public.post_comments enable row level security; alter table public.post_likes enable row level security; alter table public.post_polls enable row level security; alter table public.poll_options enable row level security; alter table public.poll_votes enable row level security; alter table public.stories enable row level security; alter table public.story_views enable row level security;
create policy posts_read on public.posts for select to authenticated using(public.can_read_post(posts)); create policy posts_insert on public.posts for insert to authenticated with check(author_id=auth.uid() and public.has_permission('posts.create',campus_id)); create policy posts_update on public.posts for update to authenticated using(author_id=auth.uid() or public.has_permission('posts.moderate',campus_id)) with check(author_id=auth.uid() or public.has_permission('posts.moderate',campus_id)); create policy posts_delete on public.posts for delete to authenticated using(public.has_permission('posts.moderate',campus_id));
create policy post_media_read on public.post_media for select to authenticated using(exists(select 1 from public.posts p where p.id=post_id and public.can_read_post(p))); create policy post_media_write on public.post_media for all to authenticated using(exists(select 1 from public.posts p where p.id=post_id and p.author_id=auth.uid())) with check(exists(select 1 from public.posts p where p.id=post_id and p.author_id=auth.uid()));
create policy post_comments_read on public.post_comments for select to authenticated using(exists(select 1 from public.posts p where p.id=post_id and public.can_read_post(p))); create policy post_comments_insert on public.post_comments for insert to authenticated with check(author_id=auth.uid() and exists(select 1 from public.posts p where p.id=post_id and public.can_read_post(p))); create policy post_comments_update on public.post_comments for update to authenticated using(author_id=auth.uid() or public.has_permission('posts.moderate')) with check(author_id=auth.uid() or public.has_permission('posts.moderate')); create policy post_comments_delete on public.post_comments for delete to authenticated using(public.has_permission('posts.moderate'));
create policy post_likes_read on public.post_likes for select to authenticated using(exists(select 1 from public.posts p where p.id=post_id and public.can_read_post(p))); create policy post_likes_insert on public.post_likes for insert to authenticated with check(user_id=auth.uid()); create policy post_likes_delete on public.post_likes for delete to authenticated using(user_id=auth.uid());
create policy post_polls_read on public.post_polls for select to authenticated using(exists(select 1 from public.posts p where p.id=post_id and public.can_read_post(p))); create policy post_polls_write on public.post_polls for all to authenticated using(exists(select 1 from public.posts p where p.id=post_id and p.author_id=auth.uid())) with check(exists(select 1 from public.posts p where p.id=post_id and p.author_id=auth.uid())); create policy poll_options_read on public.poll_options for select to authenticated using(exists(select 1 from public.post_polls pp join public.posts p on p.id=pp.post_id where pp.id=poll_id and public.can_read_post(p))); create policy poll_options_write on public.poll_options for all to authenticated using(exists(select 1 from public.post_polls pp join public.posts p on p.id=pp.post_id where pp.id=poll_id and p.author_id=auth.uid())) with check(exists(select 1 from public.post_polls pp join public.posts p on p.id=pp.post_id where pp.id=poll_id and p.author_id=auth.uid()));
create policy poll_votes_read on public.poll_votes for select to authenticated using(voter_id=auth.uid() or public.has_permission('posts.moderate')); create policy poll_votes_insert on public.poll_votes for insert to authenticated with check(voter_id=auth.uid()); create policy poll_votes_delete on public.poll_votes for delete to authenticated using(voter_id=auth.uid());
create policy stories_read on public.stories for select to authenticated using(deleted_at is null and status='active' and expires_at>timezone('utc',now()) and (author_id=auth.uid() or visibility='public' or campus_id=(select campus_id from public.profiles where id=auth.uid()))); create policy stories_insert on public.stories for insert to authenticated with check(author_id=auth.uid() and public.has_permission('stories.create',campus_id)); create policy stories_update on public.stories for update to authenticated using(author_id=auth.uid() or public.has_permission('stories.moderate')) with check(author_id=auth.uid() or public.has_permission('stories.moderate')); create policy stories_delete on public.stories for delete to authenticated using(public.has_permission('stories.moderate'));
create policy story_views_read on public.story_views for select to authenticated using(viewer_id=auth.uid() or exists(select 1 from public.stories s where s.id=story_id and s.author_id=auth.uid())); create policy story_views_insert on public.story_views for insert to authenticated with check(viewer_id=auth.uid());
